package br.senai.plataformadigital.academicpi;
import br.senai.plataformadigital.auth.api.authorization.AuthenticatedSubjectProvider; import java.util.List; import java.util.UUID; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/coordination/audit") @ConditionalOnProperty(name="spring.datasource.url")
public class InstitutionalAuditController { private final InstitutionalAuditRepository repository; private final StudentAdministrationRepository students; private final AuthenticatedSubjectProvider subjects; public InstitutionalAuditController(InstitutionalAuditRepository repository, StudentAdministrationRepository students, AuthenticatedSubjectProvider subjects){this.repository=repository;this.students=students;this.subjects=subjects;} @GetMapping List<AuditResponse> list(){UUID actor=subjects.currentSubject().map(s->UUID.fromString(s.id())).orElseThrow();if(!students.isCoordinator(actor))throw new br.senai.plataformadigital.exception.ConflictException("A operação exige papel de coordenação.");return repository.findAll();} }
